package com.performance.demo;

import java.util.concurrent.ExecutorService;

import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StringConcurrencyDemo {
    private static final int ITERATIONS = 1000;

    public static void main(String[] args) throws InterruptedException {
        // StringBuilder in a concurrent context (unsafe)
        StringBuilder unsafeBuilder = new StringBuilder();
        // StringBuffer in a concurrent context (safe)
        StringBuffer safeBuffer = new StringBuffer();

        ExecutorService executor = Executors.newFixedThreadPool(10);

        for (int i = 0; i < ITERATIONS; i++) {
            executor.submit(() -> {
                unsafeBuilder.append("A");
                safeBuffer.append("A");
            });
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        // StringBuilder length will likely be less than ITERATIONS due to race conditions
        System.out.println("StringBuilder final length: " + unsafeBuilder.length());
        // StringBuffer length will always be exactly ITERATIONS
        System.out.println("StringBuffer final length: " + safeBuffer.length());
    }
}
